mapper.update:
UPDATE training_goals
SET target_count = #{targetCount}
WHERE user_id = #{userId}

UPDATE notification_settings
SET practice_reminder_enabled = #{reminderOn},
    report_notice_enabled = #{reportNoticeOn},
    goal_notice_enabled = #{goalNoticeOn},
    reminder_time = #{reminderTime}
WHERE user_id = #{userId}

UPDATE privacy_settings
SET keep_training_history = #{keepHistory},
    allow_anonymous_stats = #{anonymousStats}
WHERE user_id = #{userId}

UPDATE users
SET nickname = #{nickname}, school = #{school}, major = #{major}, bio = #{bio}
WHERE user_id = #{userId}

UPDATE users
SET avatar_mime = #{mimeType}, avatar_data = #{avatarData,jdbcType=BLOB}
WHERE user_id = #{userId}

mapper.select:
SELECT avatar_mime AS mime_type, avatar_data AS data
FROM users
WHERE user_id = #{userId}
